/* Original movement instructions, aligned across the seven supported locales. */
const MOVEMENT_LANGS = ["en", "fr", "es", "de", "it", "nl", "ar"];
const MOVEMENT_COPY = {
  "bench": ["Lie back on the bench with feet planted. Lower the weight toward your chest, then press it up.", "Allongez-vous sur le banc, pieds au sol. Descendez la charge vers la poitrine, puis poussez vers le haut.", "Túmbate en el banco con los pies apoyados. Baja el peso hacia el pecho y después empújalo hacia arriba.", "Lege dich mit festen Füßen auf die Bank. Senke das Gewicht zur Brust und drücke es dann nach oben.", "Sdraiati sulla panca con i piedi a terra. Abbassa il carico verso il petto, poi spingilo in alto.", "Ga met je voeten op de grond op de bank liggen. Laat het gewicht naar je borst zakken en druk het omhoog.", "استلقِ على المقعد وقدماك ثابتتان. أنزل الوزن نحو صدرك، ثم ادفعه إلى أعلى."],
  "chestMachine": ["Sit with feet planted and handles at chest height. Press forward, then slowly bring the handles back.", "Asseyez-vous, pieds au sol et poignées à hauteur de poitrine. Poussez vers l’avant, puis ramenez lentement les poignées.", "Siéntate con los pies apoyados y las asas a la altura del pecho. Empuja hacia delante y vuelve despacio.", "Setze dich mit festen Füßen und Griffen auf Brusthöhe hin. Drücke nach vorn und führe die Griffe langsam zurück.", "Siediti con piedi a terra e maniglie all’altezza del petto. Spingi in avanti, poi riporta lentamente le maniglie.", "Ga zitten met je voeten op de grond en de grepen op borsthoogte. Druk naar voren en breng de grepen langzaam terug.", "اجلس وقدماك ثابتتان والمقبضان عند مستوى الصدر. ادفع إلى الأمام ثم أعد المقبضين ببطء."],
  "incline": ["Set a low incline and plant your feet. Lower the dumbbells beside your upper chest, then press up.", "Réglez une faible inclinaison et posez les pieds au sol. Descendez les haltères près du haut de la poitrine, puis poussez.", "Ajusta una inclinación baja y apoya los pies. Baja las mancuernas junto a la parte alta del pecho y empuja hacia arriba.", "Stelle eine leichte Neigung ein und setze die Füße auf. Senke die Hanteln neben die obere Brust und drücke sie hoch.", "Imposta una leggera inclinazione e appoggia i piedi. Abbassa i manubri ai lati della parte alta del petto, poi spingi in alto.", "Stel een lichte helling in en zet je voeten neer. Laat de dumbbells naast je bovenborst zakken en druk omhoog.", "اضبط ميلاً منخفضاً وثبّت قدميك. أنزل الدمبلين بجانب أعلى الصدر ثم ادفعهما إلى أعلى."],
  "fly": ["Lie on a flat bench. With elbows softly bent, open your arms to a comfortable stretch, then bring the weights together over your chest.", "Allongez-vous sur un banc plat. Coudes légèrement fléchis, ouvrez les bras jusqu’à un étirement confortable, puis rapprochez les haltères au-dessus de la poitrine.", "Túmbate en un banco plano. Con los codos ligeramente flexionados, abre los brazos hasta un estiramiento cómodo y junta las pesas sobre el pecho.", "Lege dich auf eine flache Bank. Öffne die Arme mit leicht gebeugten Ellenbogen bis zur angenehmen Dehnung und führe die Gewichte über der Brust zusammen.", "Sdraiati su una panca piana. Con gomiti leggermente piegati, apri le braccia fino a un allungamento confortevole, poi riunisci i pesi sul petto.", "Ga op een vlakke bank liggen. Open je armen met licht gebogen ellebogen tot een prettige rek en breng de gewichten boven je borst samen.", "استلقِ على مقعد مستوٍ. افتح ذراعيك مع ثني المرفقين قليلاً حتى تمدد مريح، ثم قرّب الوزنين فوق الصدر."],
  "cableFly": ["Stand between the cables with knees soft. Bring the handles together in front of your chest, then slowly open your arms.", "Debout entre les câbles, genoux souples, rapprochez les poignées devant la poitrine, puis ouvrez lentement les bras.", "De pie entre las poleas, con las rodillas suaves, junta las asas delante del pecho y abre los brazos lentamente.", "Stehe mit lockeren Knien zwischen den Kabeln. Führe die Griffe vor der Brust zusammen und öffne die Arme langsam.", "In piedi tra i cavi, con ginocchia morbide, unisci le maniglie davanti al petto e riapri lentamente le braccia.", "Sta met soepele knieën tussen de kabels. Breng de grepen voor je borst samen en open je armen langzaam.", "قف بين الكابلين مع إرخاء الركبتين. قرّب المقبضين أمام الصدر ثم افتح الذراعين ببطء."],
  "pushup": ["Place your hands under or slightly wider than your shoulders and keep your body straight. Lower your chest, then push the floor away.", "Placez les mains sous les épaules ou un peu plus largement, corps aligné. Descendez la poitrine, puis repoussez le sol.", "Coloca las manos bajo los hombros o algo más separadas y mantén el cuerpo recto. Baja el pecho y empuja el suelo.", "Setze die Hände unter oder etwas breiter als die Schultern auf und halte den Körper gerade. Senke die Brust und drücke den Boden weg.", "Mani sotto o poco oltre la larghezza delle spalle, corpo allineato. Abbassa il petto, poi spingi via il pavimento.", "Zet je handen onder of iets breder dan je schouders en houd je lichaam recht. Laat je borst zakken en duw de vloer weg.", "ضع يديك تحت الكتفين أو أوسع قليلاً وحافظ على استقامة الجسم. أنزل الصدر ثم ادفع الأرض بعيداً."],
  "dip": ["Support yourself on the bars. Bend your elbows to lower within a comfortable shoulder range, then press up.", "En appui sur les barres, fléchissez les coudes pour descendre sans gêne aux épaules, puis repoussez.", "Apóyate en las barras. Flexiona los codos para bajar dentro de un rango cómodo para los hombros y empuja hacia arriba.", "Stütze dich auf die Barren. Beuge die Ellenbogen und senke dich in einem angenehmen Schulterbereich, dann drücke dich hoch.", "Sostieniti sulle parallele. Piega i gomiti per scendere entro un’ampiezza confortevole per le spalle, poi spingi in alto.", "Steun op de stangen. Buig je ellebogen en zak binnen een prettige schouderbeweging, druk jezelf daarna omhoog.", "اسند جسمك على المتوازيين. اثنِ المرفقين لتنزل ضمن مدى مريح للكتفين ثم ادفع إلى أعلى."],
  "overhead": ["Stand tall with the weight at shoulder height. Press overhead without leaning back, then lower to your shoulders.", "Debout, charge à hauteur d’épaules, poussez au-dessus de la tête sans cambrer, puis redescendez aux épaules.", "De pie, con el peso a la altura de los hombros, empuja sobre la cabeza sin arquear la espalda y vuelve a bajar.", "Stehe aufrecht mit dem Gewicht auf Schulterhöhe. Drücke über den Kopf ohne ins Hohlkreuz zu fallen, dann senke es zu den Schultern.", "In piedi, carico all’altezza delle spalle, spingi sopra la testa senza inarcare la schiena, poi riabbassa alle spalle.", "Sta rechtop met het gewicht op schouderhoogte. Druk boven je hoofd zonder achterover te leunen en laat het terugzakken.", "قف منتصباً والوزن عند الكتفين. ادفع فوق الرأس دون تقويس الظهر ثم أنزل الوزن للكتفين."],
  "lateral": ["Stand tall with a weight or low cable at your side. Raise your arm or arms out toward shoulder height, then lower.", "Debout, charge ou câble bas sur le côté, levez le ou les bras latéralement jusqu’à hauteur d’épaules, puis redescendez.", "De pie, con una pesa o polea baja al lado, eleva uno o ambos brazos lateralmente hasta la altura de los hombros y baja.", "Stehe aufrecht mit Gewicht oder tiefem Kabel seitlich. Hebe einen oder beide Arme seitlich etwa auf Schulterhöhe und senke sie.", "In piedi con peso o cavo basso al fianco, alza lateralmente uno o entrambi i bracci fino all’altezza delle spalle, poi abbassa.", "Sta rechtop met een gewicht of lage kabel naast je. Hef één of beide armen zijwaarts tot schouderhoogte en laat ze zakken.", "قف منتصباً والوزن أو الكابل المنخفض بجانبك. ارفع ذراعاً أو الذراعين جانبياً حتى مستوى الكتفين ثم أنزل."],
  "rearFly": ["Hinge at your hips with knees soft. Raise your arms out and back with elbows slightly bent, then lower.", "Penchez-vous aux hanches, genoux souples. Levez les bras sur les côtés et vers l’arrière, coudes légèrement fléchis, puis redescendez.", "Inclínate desde las caderas con las rodillas suaves. Eleva los brazos hacia los lados y atrás con los codos ligeramente flexionados y baja.", "Beuge dich aus der Hüfte nach vorn, Knie locker. Hebe die Arme mit leicht gebeugten Ellenbogen seitlich und nach hinten, dann senke sie.", "Piegati dalle anche con ginocchia morbide. Alza le braccia verso i lati e indietro con gomiti leggermente piegati, poi abbassa.", "Buig vanuit je heupen met soepele knieën. Hef je armen zijwaarts en naar achteren met licht gebogen ellebogen en laat ze zakken.", "انحنِ من الوركين مع إرخاء الركبتين. ارفع الذراعين جانباً وخلفاً مع ثني خفيف للمرفقين ثم أنزل."],
  "pullup": ["Grip the overhead bar. Pull until your chin approaches the bar, then lower to a controlled hang.", "Saisissez la barre au-dessus de vous. Tirez jusqu’à approcher le menton de la barre, puis redescendez en contrôlant la suspension.", "Agarra la barra sobre tu cabeza. Tira hasta acercar la barbilla a la barra y baja controlando la suspensión.", "Greife die Stange über dir. Ziehe dich hoch, bis das Kinn nahe an die Stange kommt, und senke dich kontrolliert in den Hang.", "Afferra la sbarra sopra la testa. Tira fino ad avvicinare il mento alla sbarra, poi scendi in sospensione controllata.", "Pak de stang boven je vast. Trek op tot je kin de stang nadert en zak gecontroleerd terug in de hang.", "أمسك العقلة فوق رأسك. اسحب حتى يقترب الذقن من العقلة ثم انزل إلى التعليق بتحكم."],
  "pulldown": ["Sit with your thighs braced and grip overhead. Pull the handle to your upper chest, then slowly reach up.", "Assis, cuisses calées, saisissez la poignée en hauteur. Tirez-la vers le haut de la poitrine, puis tendez lentement les bras.", "Siéntate con los muslos sujetos y agarra arriba. Tira del asa hacia la parte alta del pecho y estira los brazos lentamente.", "Setze dich mit fixierten Oberschenkeln hin und greife oben. Ziehe den Griff zur oberen Brust und strecke die Arme langsam.", "Siediti con le cosce bloccate e afferra in alto. Tira la maniglia verso la parte alta del petto, poi distendi lentamente le braccia.", "Zit met je bovenbenen vast en pak boven je vast. Trek de greep naar je bovenborst en strek je armen langzaam.", "اجلس مع تثبيت الفخذين وأمسك المقبض أعلى منك. اسحبه إلى أعلى الصدر ثم مدّ الذراعين ببطء."],
  "hingeRow": ["Hinge at your hips with hands below shoulders. Pull the bar toward your lower ribs, then extend your arms without swinging.", "Penchez-vous aux hanches, mains sous les épaules. Tirez la barre vers les côtes basses, puis tendez les bras sans élan.", "Inclínate desde las caderas con las manos bajo los hombros. Tira de la barra hacia las costillas inferiores y estira los brazos sin impulso.", "Beuge dich aus der Hüfte, Hände unter den Schultern. Ziehe die Stange zu den unteren Rippen und strecke die Arme ohne Schwung.", "Piegati dalle anche con le mani sotto le spalle. Tira il bilanciere verso le costole basse, poi distendi le braccia senza slancio.", "Buig vanuit je heupen met je handen onder je schouders. Trek de stang naar je onderste ribben en strek je armen zonder te zwaaien.", "انحنِ من الوركين واليدان تحت الكتفين. اسحب البار نحو أسفل الأضلاع ثم مدّ الذراعين دون تأرجح."],
  "supportedRow": ["Brace one hand and knee on a bench, weight in the other hand. Pull toward your hip, then lower.", "Prenez appui sur un banc avec une main et un genou, charge dans l’autre main. Tirez vers la hanche, puis redescendez.", "Apoya una mano y una rodilla en un banco, con la pesa en la otra mano. Tira hacia la cadera y baja.", "Stütze eine Hand und ein Knie auf der Bank ab, Gewicht in der anderen Hand. Ziehe zur Hüfte und senke es.", "Appoggia una mano e un ginocchio sulla panca, peso nell’altra mano. Tira verso l’anca, poi abbassa.", "Steun met één hand en knie op een bank, gewicht in de andere hand. Trek naar je heup en laat zakken.", "اسند يداً وركبة على مقعد وأمسك الوزن باليد الأخرى. اسحبه نحو الورك ثم أنزله."],
  "seatedRow": ["Sit tall with arms forward holding the handle or band. Draw your elbows toward your sides, then extend without rounding your back.", "Assis droit, bras tendus devant avec la poignée ou l’élastique, ramenez les coudes près du corps puis retendez sans arrondir le dos.", "Siéntate erguido con los brazos delante sujetando el asa o la banda. Lleva los codos a los lados y estira sin redondear la espalda.", "Sitze aufrecht mit Griff oder Band in den nach vorn gestreckten Händen. Ziehe die Ellenbogen an die Seiten und strecke ohne Rundrücken.", "Siediti eretto con le braccia avanti e la maniglia o l’elastico in mano. Porta i gomiti ai fianchi, poi distendi senza arrotondare la schiena.", "Zit rechtop met de greep of band in je uitgestrekte handen. Trek je ellebogen naar je zij en strek zonder je rug te bollen.", "اجلس منتصباً والذراعان أمامك تحملان المقبض أو الشريط. اسحب المرفقين إلى جانبيك ثم مدّ الذراعين دون تدوير الظهر."],
  "supportedMachine": ["Set your chest against the pad with feet planted. Pull the handles to your sides, then let your arms lengthen.", "Posez la poitrine contre le coussin, pieds au sol. Tirez les poignées vers les côtés, puis laissez les bras se tendre.", "Apoya el pecho en el cojín y los pies en el suelo. Tira de las asas hacia los lados y deja que los brazos se estiren.", "Lehne die Brust an das Polster, Füße am Boden. Ziehe die Griffe zu den Seiten und strecke die Arme wieder.", "Appoggia il petto al cuscino e i piedi a terra. Tira le maniglie ai fianchi, poi lascia distendere le braccia.", "Plaats je borst tegen het kussen en je voeten op de grond. Trek de grepen naar je zij en laat je armen weer strekken.", "اسند صدرك إلى الوسادة وثبّت قدميك. اسحب المقبضين إلى جانبيك ثم مدّ ذراعيك."],
  "facePull": ["Face a high cable with arms forward. Pull the handles toward your face with elbows out, then slowly reach forward.", "Face à un câble haut, bras tendus, tirez les poignées vers le visage, coudes ouverts, puis retendez lentement.", "Frente a una polea alta y con los brazos extendidos, tira de las asas hacia la cara con los codos abiertos y vuelve despacio.", "Stehe vor einem hohen Kabel mit Armen nach vorn. Ziehe die Griffe mit offenen Ellenbogen zum Gesicht und strecke langsam wieder.", "Di fronte a un cavo alto, braccia avanti, tira le maniglie verso il viso con i gomiti aperti, poi distendi lentamente.", "Sta voor een hoge kabel met je armen naar voren. Trek de grepen naar je gezicht met ellebogen naar buiten en strek langzaam terug.", "قف أمام كابل مرتفع وذراعاك للأمام. اسحب المقبضين نحو الوجه مع فتح المرفقين ثم مدّ الذراعين ببطء."],
  "squat": ["Stand with feet about shoulder width. Bend hips and knees to squat comfortably, then press through your whole foot to stand.", "Debout, pieds environ à largeur d’épaules, fléchissez hanches et genoux sans inconfort, puis poussez dans tout le pied pour vous relever.", "De pie, pies aproximadamente al ancho de hombros, flexiona caderas y rodillas cómodamente y empuja con todo el pie para subir.", "Stehe etwa schulterbreit. Beuge Hüfte und Knie angenehm tief und drücke dich über den ganzen Fuß wieder hoch.", "In piedi, piedi circa alla larghezza delle spalle, piega anche e ginocchia senza fastidio, poi spingi su tutto il piede per rialzarti.", "Sta met je voeten ongeveer op schouderbreedte. Buig je heupen en knieën comfortabel en duw via je hele voet weer omhoog.", "قف والقدمان بعرض الكتفين تقريباً. اثنِ الوركين والركبتين لمدى مريح ثم ادفع بكامل القدم للنهوض."],
  "legPress": ["Sit against the backrest with feet on the plate. Bend your knees comfortably, then press the plate away without locking them.", "Dos contre le dossier, pieds sur la plateforme, fléchissez les genoux confortablement puis poussez sans les verrouiller.", "Siéntate contra el respaldo con los pies en la plataforma. Flexiona las rodillas cómodamente y empuja sin bloquearlas.", "Sitze am Rückenpolster mit Füßen auf der Platte. Beuge die Knie angenehm weit und drücke die Platte weg, ohne die Knie zu verriegeln.", "Siediti contro lo schienale, piedi sulla pedana. Piega le ginocchia in modo confortevole, poi spingi senza bloccarle.", "Zit tegen de rugleuning met je voeten op de plaat. Buig je knieën comfortabel en duw de plaat weg zonder je knieën op slot te zetten.", "اجلس مسنداً ظهرك وقدماك على اللوح. اثنِ الركبتين لمدى مريح ثم ادفع اللوح دون قفل الركبتين."],
  "split": ["Put your rear foot on a bench and your front foot on the floor. Bend the front knee to lower, then push through that foot to rise.", "Placez le pied arrière sur un banc et le pied avant au sol. Fléchissez le genou avant pour descendre, puis poussez sur ce pied pour remonter.", "Coloca el pie trasero en un banco y el delantero en el suelo. Flexiona la rodilla delantera para bajar y empuja con ese pie para subir.", "Stelle den hinteren Fuß auf eine Bank und den vorderen auf den Boden. Beuge das vordere Knie zum Absenken und drücke dich über diesen Fuß hoch.", "Metti il piede posteriore sulla panca e quello anteriore a terra. Piega il ginocchio davanti per scendere, poi spingi con quel piede per salire.", "Zet je achterste voet op een bank en je voorste voet op de grond. Buig je voorste knie om te zakken en duw via die voet omhoog.", "ضع القدم الخلفية على مقعد والأمامية على الأرض. اثنِ الركبة الأمامية للنزول ثم ادفع بهذه القدم للنهوض."],
  "lunge": ["Step forward and lower into a lunge. Push up, bring the back leg through into the next step, and alternate sides.", "Avancez et descendez en fente. Remontez, faites passer la jambe arrière pour le pas suivant et alternez les côtés.", "Da un paso y baja en zancada. Sube, lleva la pierna de atrás al siguiente paso y alterna los lados.", "Mache einen Schritt nach vorn und senke dich in den Ausfallschritt. Drücke dich hoch, führe das hintere Bein zum nächsten Schritt und wechsle die Seite.", "Fai un passo avanti e scendi in affondo. Risali, porta la gamba posteriore nel passo successivo e alterna i lati.", "Stap naar voren en zak in een uitval. Duw jezelf omhoog, breng het achterste been naar de volgende stap en wissel van kant.", "تقدم وانزل في وضع الطعن. ادفع للنهوض ومرّر الساق الخلفية إلى الخطوة التالية، ثم بدّل الجانبين."],
  "stepUp": ["Place one foot fully on a stable step. Stand through that foot, then step down with control; repeat on both sides.", "Posez un pied entièrement sur une marche stable. Montez en poussant sur ce pied, puis redescendez avec contrôle ; alternez les côtés.", "Apoya un pie completo en un escalón estable. Sube con ese pie y baja con control; repite por ambos lados.", "Setze einen Fuß vollständig auf eine stabile Stufe. Steige über diesen Fuß hoch und kontrolliert wieder ab; wiederhole beidseitig.", "Appoggia un piede interamente su un gradino stabile. Sali spingendo con quel piede, poi scendi con controllo; ripeti da entrambi i lati.", "Zet één voet volledig op een stabiele trede. Stap via die voet omhoog en stap gecontroleerd terug; herhaal aan beide kanten.", "ضع قدمك كاملة على درجة ثابتة. اصعد بالضغط على تلك القدم ثم انزل بتحكم؛ كرر على الجانبين."],
  "legExt": ["Sit with your back supported and knees bent. Straighten the knee, then lower slowly; work both sides.", "Assis, dos soutenu et genoux fléchis, tendez le genou puis redescendez lentement ; travaillez les deux côtés.", "Siéntate con la espalda apoyada y las rodillas flexionadas. Estira la rodilla y baja despacio; trabaja ambos lados.", "Sitze mit gestütztem Rücken und gebeugten Knien. Strecke das Knie und senke langsam; trainiere beide Seiten.", "Siediti con schiena sostenuta e ginocchia piegate. Distendi il ginocchio, poi abbassa lentamente; lavora entrambi i lati.", "Zit met gesteunde rug en gebogen knieën. Strek je knie en laat langzaam zakken; train beide kanten.", "اجلس مسند الظهر وركبتاك مثنيتان. مدّ الركبة ثم أنزل ببطء؛ درّب الجانبين."],
  "deadlift": ["Stand with the bar over mid-foot. Hinge and bend your knees to grip it, push the floor away to stand, then return the bar to the floor.", "Placez la barre au-dessus du milieu des pieds. Fléchissez hanches et genoux pour la saisir, poussez dans le sol pour vous relever, puis reposez-la.", "Coloca la barra sobre la mitad del pie. Flexiona caderas y rodillas para agarrarla, empuja el suelo para levantarte y devuelve la barra al suelo.", "Stelle die Stange über die Fußmitte. Beuge Hüfte und Knie zum Greifen, drücke den Boden weg und richte dich auf; lege die Stange wieder ab.", "Posiziona il bilanciere sopra metà piede. Piega anche e ginocchia per afferrarlo, spingi sul pavimento per alzarti e riportalo a terra.", "Zet de stang boven het midden van je voet. Buig heupen en knieën om haar vast te pakken, duw de vloer weg om op te staan en zet de stang terug.", "قف والبار فوق منتصف القدم. اثنِ الوركين والركبتين لإمساكه وادفع الأرض للنهوض، ثم أعد البار إلى الأرض."],
  "rdl": ["Stand holding the weights. Push your hips back with soft knees, slide the weights down your legs to a comfortable stretch, then stand tall.", "Debout, charges en main, reculez les hanches, genoux souples, et faites glisser les charges le long des jambes jusqu’à un étirement confortable, puis relevez-vous.", "De pie con las pesas, lleva las caderas atrás con las rodillas suaves y desliza las pesas por las piernas hasta un estiramiento cómodo; vuelve a subir.", "Stehe mit den Gewichten in den Händen. Schiebe die Hüfte mit lockeren Knien zurück, führe die Gewichte bis zur angenehmen Dehnung an den Beinen entlang und richte dich auf.", "In piedi con i pesi, porta le anche indietro e tieni le ginocchia morbide. Fai scorrere i pesi lungo le gambe fino a un allungamento confortevole, poi risali.", "Sta met de gewichten in je handen. Duw je heupen naar achter met soepele knieën, laat de gewichten langs je benen zakken tot een prettige rek en kom omhoog.", "قف حاملاً الأوزان. ادفع الوركين للخلف مع إرخاء الركبتين ومرّر الأوزان بمحاذاة الساقين حتى تمدد مريح، ثم انتصب."],
  "hipThrust": ["Rest your upper back on a bench with feet flat. Drive your hips up until your torso aligns with your thighs, then lower.", "Haut du dos sur un banc, pieds à plat, poussez les hanches vers le haut jusqu’à aligner le buste et les cuisses, puis redescendez.", "Apoya la parte alta de la espalda en un banco y los pies en el suelo. Eleva las caderas hasta alinear el tronco con los muslos y baja.", "Lehne den oberen Rücken an eine Bank, Füße flach. Hebe die Hüfte, bis Rumpf und Oberschenkel eine Linie bilden, und senke sie.", "Appoggia la parte alta della schiena alla panca, piedi a terra. Solleva le anche fino ad allineare busto e cosce, poi scendi.", "Steun met je bovenrug op een bank, voeten plat. Duw je heupen omhoog tot romp en bovenbenen één lijn vormen en laat zakken.", "اسند أعلى ظهرك إلى مقعد وثبّت قدميك. ارفع الوركين حتى يستقيم الجذع مع الفخذين ثم انزل."],
  "legCurl": ["Sit against the pad with legs extended and the roller above your heels. Bend your knees to draw it down, then return.", "Assis contre le dossier, jambes tendues et rouleau au-dessus des talons, fléchissez les genoux pour l’abaisser, puis revenez.", "Siéntate contra el respaldo con las piernas extendidas y el rodillo sobre los talones. Flexiona las rodillas para bajarlo y vuelve.", "Sitze am Polster mit gestreckten Beinen und Rolle über den Fersen. Beuge die Knie, um die Rolle zu senken, und führe sie zurück.", "Siediti contro lo schienale, gambe distese e rullo sopra i talloni. Piega le ginocchia per abbassarlo, poi ritorna.", "Zit tegen het kussen met gestrekte benen en de rol boven je hielen. Buig de knieën om de rol te laten zakken en keer terug.", "اجلس مسنداً ظهرك والساقان ممدودتان والأسطوانة فوق الكعبين. اثنِ الركبتين لسحبها للأسفل ثم عد."],
  "backExt": ["Lie face down and gently lift your chest while keeping your hips on the floor. Lower without throwing your head back.", "Allongé sur le ventre, soulevez doucement la poitrine en gardant les hanches au sol. Redescendez sans jeter la tête en arrière.", "Túmbate boca abajo y eleva suavemente el pecho manteniendo las caderas en el suelo. Baja sin echar la cabeza atrás.", "Lege dich auf den Bauch und hebe die Brust sanft, während die Hüfte am Boden bleibt. Senke sie, ohne den Kopf zurückzuwerfen.", "Sdraiati a pancia in giù e solleva dolcemente il petto tenendo le anche a terra. Scendi senza gettare indietro la testa.", "Ga op je buik liggen en hef je borst rustig terwijl je heupen op de vloer blijven. Zak terug zonder je hoofd achterover te gooien.", "استلقِ على بطنك وارفع صدرك برفق مع إبقاء الوركين على الأرض. انزل دون إرجاع الرأس للخلف بعنف."],
  "calf": ["Stand on the balls of your feet, holding support if needed. Rise onto your toes, then lower your heels with control.", "Debout sur l’avant des pieds, avec un appui si nécessaire, montez sur la pointe des pieds puis abaissez les talons avec contrôle.", "De pie sobre la parte delantera de los pies, con apoyo si hace falta, sube a puntillas y baja los talones con control.", "Stehe auf den Fußballen, halte dich bei Bedarf fest. Hebe die Fersen und senke sie kontrolliert.", "In piedi sull’avampiede, con un sostegno se serve, sollevati sulle punte e abbassa i talloni con controllo.", "Sta op je voorvoeten en houd je zo nodig vast. Kom op je tenen en laat je hielen gecontroleerd zakken.", "قف على مقدمة القدمين واستند عند الحاجة. ارتفع على الأصابع ثم أنزل الكعبين بتحكم."],
  "seatedCalf": ["Sit with the balls of your feet on a block and knees under the pad. Lift your heels, pause, then lower.", "Assis, avant des pieds sur une cale et genoux sous le coussin, levez les talons, marquez une pause puis redescendez.", "Siéntate con la parte delantera de los pies sobre un bloque y las rodillas bajo el cojín. Eleva los talones, pausa y baja.", "Sitze mit den Fußballen auf einem Block und Knien unter dem Polster. Hebe die Fersen, halte kurz und senke sie.", "Siediti con avampiedi su un rialzo e ginocchia sotto il cuscino. Solleva i talloni, fermati, poi abbassa.", "Zit met je voorvoeten op een blok en knieën onder het kussen. Hef je hielen, pauzeer en laat zakken.", "اجلس ومقدمتا القدمين على قاعدة والركبتان تحت الوسادة. ارفع الكعبين وتوقف قليلاً ثم أنزل."],
  "curl": ["Stand tall with elbows close to your sides. Curl the weight toward your shoulders, then lower without swinging.", "Debout, coudes près du corps, montez la charge vers les épaules puis redescendez sans élan.", "De pie con los codos cerca del cuerpo, eleva el peso hacia los hombros y baja sin balancearte.", "Stehe aufrecht, Ellenbogen nah am Körper. Beuge die Arme zum Anheben des Gewichts Richtung Schultern und senke ohne Schwung.", "In piedi con gomiti vicino ai fianchi, porta il peso verso le spalle e riabbassalo senza oscillare.", "Sta rechtop met ellebogen dicht bij je zij. Breng het gewicht naar je schouders en laat zakken zonder te zwaaien.", "قف منتصباً والمرفقان قرب الجانبين. ارفع الوزن نحو الكتفين ثم أنزله دون تأرجح."],
  "pushdown": ["Face the high cable or band with elbows by your sides. Straighten your elbows to press down, then return slowly.", "Face au câble haut ou à l’élastique, coudes près du corps, tendez les coudes vers le bas puis revenez lentement.", "Frente a la polea alta o banda, con los codos pegados al cuerpo, estíralos para empujar hacia abajo y vuelve lentamente.", "Stehe vor dem hohen Kabel oder Band, Ellenbogen am Körper. Strecke die Ellenbogen nach unten und führe langsam zurück.", "Di fronte al cavo alto o elastico, gomiti ai fianchi, distendi i gomiti verso il basso e ritorna lentamente.", "Sta voor de hoge kabel of band met ellebogen naast je zij. Strek je ellebogen naar beneden en keer langzaam terug.", "قف أمام كابل مرتفع أو شريط والمرفقان بجانبك. مدّ المرفقين للضغط للأسفل ثم عد ببطء."],
  "overheadExt": ["Hold the weight overhead with elbows pointing up. Bend your elbows to lower it behind your head, then extend.", "Tenez la charge au-dessus de la tête, coudes vers le haut. Fléchissez-les pour descendre derrière la tête, puis tendez-les.", "Sujeta el peso sobre la cabeza con los codos hacia arriba. Flexiónalos para bajarlo detrás de la cabeza y vuelve a estirar.", "Halte das Gewicht über dem Kopf, Ellenbogen zeigen hoch. Beuge sie, um es hinter den Kopf zu senken, und strecke sie wieder.", "Tieni il peso sopra la testa con gomiti verso l’alto. Piegali per abbassarlo dietro la testa, poi distendili.", "Houd het gewicht boven je hoofd met ellebogen omhoog. Buig ze om het achter je hoofd te laten zakken en strek ze weer.", "أمسك الوزن فوق الرأس والمرفقان للأعلى. اثنهما لإنزال الوزن خلف الرأس ثم مدّهما."],
  "skull": ["Lie on a bench with arms above your chest. Bend elbows to bring the weight toward your forehead, then straighten them.", "Allongez-vous sur un banc, bras au-dessus de la poitrine. Fléchissez les coudes pour approcher la charge du front, puis retendez.", "Túmbate en un banco con los brazos sobre el pecho. Flexiona los codos para acercar el peso a la frente y vuelve a estirarlos.", "Lege dich auf eine Bank, Arme über der Brust. Beuge die Ellenbogen, führe das Gewicht zur Stirn und strecke sie wieder.", "Sdraiati sulla panca con braccia sopra il petto. Piega i gomiti per avvicinare il peso alla fronte, poi distendili.", "Ga op een bank liggen met armen boven je borst. Buig je ellebogen om het gewicht naar je voorhoofd te brengen en strek weer.", "استلقِ على مقعد والذراعان فوق الصدر. اثنِ المرفقين لتقريب الوزن من الجبهة ثم مدّهما."],
  "wristCurl": ["Rest your forearm on your thigh, palm up and hand beyond your knee. Curl your wrist up, then lower without moving your forearm.", "Posez l’avant-bras sur la cuisse, paume vers le haut et main au-delà du genou. Fléchissez le poignet puis redescendez sans bouger l’avant-bras.", "Apoya el antebrazo en el muslo, palma arriba y mano más allá de la rodilla. Flexiona la muñeca hacia arriba y baja sin mover el antebrazo.", "Lege den Unterarm mit Handfläche nach oben auf den Oberschenkel, Hand hinter dem Knie. Beuge das Handgelenk hoch und senke ohne den Unterarm zu bewegen.", "Appoggia l’avambraccio sulla coscia, palmo in alto e mano oltre il ginocchio. Piega il polso in alto, poi abbassalo senza muovere l’avambraccio.", "Leg je onderarm op je bovenbeen, handpalm omhoog en hand voorbij je knie. Buig je pols omhoog en laat zakken zonder je onderarm te bewegen.", "اسند الساعد إلى الفخذ وراحة اليد للأعلى واليد بعد الركبة. اثنِ الرسغ للأعلى ثم أنزل دون تحريك الساعد."],
  "cableCrunch": ["Kneel facing a high cable, holding the rope beside your head. Curl your ribs toward your pelvis, then return without pulling with your arms.", "À genoux face à un câble haut, corde près de la tête, enroulez les côtes vers le bassin puis revenez sans tirer avec les bras.", "De rodillas frente a una polea alta, cuerda junto a la cabeza, acerca las costillas a la pelvis y vuelve sin tirar con los brazos.", "Knie vor einem hohen Kabel, Seil neben dem Kopf. Rolle die Rippen zum Becken und kehre zurück, ohne mit den Armen zu ziehen.", "In ginocchio di fronte a un cavo alto, corda vicino alla testa, avvicina le costole al bacino e torna senza tirare con le braccia.", "Kniel voor een hoge kabel met het touw naast je hoofd. Krul je ribben naar je bekken en keer terug zonder met je armen te trekken.", "اجثُ أمام كابل مرتفع والحبل بجانب الرأس. قرّب الأضلاع من الحوض ثم عد دون السحب بالذراعين."],
  "hangingRaise": ["Hang from a bar. Bring your knees toward your chest without swinging, then lower your legs with control.", "Suspendez-vous à une barre. Ramenez les genoux vers la poitrine sans vous balancer, puis redescendez les jambes avec contrôle.", "Cuélgate de una barra. Acerca las rodillas al pecho sin balancearte y baja las piernas con control.", "Hänge an einer Stange. Ziehe die Knie ohne Schwung zur Brust und senke die Beine kontrolliert.", "Appenditi a una sbarra. Porta le ginocchia verso il petto senza oscillare, poi abbassa le gambe con controllo.", "Hang aan een stang. Breng je knieën zonder zwaaien naar je borst en laat je benen gecontroleerd zakken.", "تعلّق بالعقلة. قرّب الركبتين من الصدر دون تأرجح ثم أنزل الساقين بتحكم."],
  "abWheel": ["Kneel with hands on the wheel under your shoulders. Roll forward only as far as you can brace, then pull back to start.", "À genoux, mains sur la roue sous les épaules, avancez seulement aussi loin que vous pouvez gainer, puis revenez.", "De rodillas, manos en la rueda bajo los hombros, rueda hacia delante solo hasta donde puedas mantener el tronco firme y vuelve.", "Knie mit den Händen am Rad unter den Schultern. Rolle nur so weit vor, wie du den Rumpf stabil halten kannst, und ziehe zurück.", "In ginocchio, mani sulla ruota sotto le spalle, rotola avanti solo fin dove riesci a mantenere il busto stabile, poi torna.", "Kniel met je handen op het wiel onder je schouders. Rol alleen zo ver naar voren als je je romp stabiel houdt en trek terug.", "اجثُ واليدان على العجلة تحت الكتفين. تدحرج للأمام فقط بقدر ما تستطيع تثبيت الجذع، ثم عد للبداية."],
  "crunch": ["Lie on your back with knees bent and the weight at your chest. Curl your shoulders off the floor, then lower without pulling your neck.", "Sur le dos, genoux fléchis, charge sur la poitrine, enroulez les épaules hors du sol puis redescendez sans tirer sur la nuque.", "Boca arriba, rodillas flexionadas y peso en el pecho, despega los hombros del suelo y baja sin tirar del cuello.", "Lege dich mit gebeugten Knien und Gewicht an der Brust auf den Rücken. Hebe die Schultern vom Boden und senke sie ohne Zug am Nacken.", "Supino, ginocchia piegate e peso sul petto, solleva le spalle dal pavimento e scendi senza tirare il collo.", "Lig op je rug met gebogen knieën en het gewicht bij je borst. Til je schouders van de vloer en zak zonder aan je nek te trekken.", "استلقِ على ظهرك والركبتان مثنيتان والوزن على الصدر. ارفع الكتفين عن الأرض ثم انزل دون شد الرقبة."],
  "pike": ["Place hands on the floor with hips high. Bend your elbows to lower your head between your hands, then press back up.", "Mains au sol, hanches hautes, fléchissez les coudes pour descendre la tête entre les mains, puis repoussez.", "Manos en el suelo y caderas altas, flexiona los codos para bajar la cabeza entre las manos y empuja hacia arriba.", "Setze die Hände auf den Boden, Hüfte hoch. Beuge die Ellenbogen und senke den Kopf zwischen die Hände, dann drücke dich hoch.", "Mani a terra e anche alte, piega i gomiti per abbassare la testa tra le mani, poi spingi in alto.", "Zet je handen op de vloer met je heupen hoog. Buig je ellebogen en laat je hoofd tussen je handen zakken, duw dan omhoog.", "ضع اليدين على الأرض والوركين مرتفعين. اثنِ المرفقين لإنزال الرأس بين اليدين ثم ادفع للأعلى."],
  "benchDip": ["Place hands on the bench edge and feet on the floor. Bend elbows to lower your hips close to the bench, then press up within a comfortable range.", "Mains au bord du banc et pieds au sol, fléchissez les coudes pour descendre les hanches près du banc, puis repoussez sans gêne.", "Manos en el borde del banco y pies en el suelo, flexiona los codos para bajar las caderas cerca del banco y sube sin molestias.", "Hände an der Bankkante, Füße am Boden. Beuge die Ellenbogen und senke die Hüfte nah an der Bank, dann drücke dich beschwerdefrei hoch.", "Mani sul bordo della panca e piedi a terra, piega i gomiti per abbassare le anche vicino alla panca, poi spingi senza fastidio.", "Handen op de bankrand, voeten op de grond. Buig je ellebogen en laat je heupen dicht bij de bank zakken; duw comfortabel omhoog.", "ضع اليدين على حافة المقعد والقدمين على الأرض. اثنِ المرفقين لإنزال الوركين قرب المقعد ثم ادفع ضمن مدى مريح."],
  "hang": ["Grip an overhead bar and let your body hang with shoulders active. Keep breathing and step down with control.", "Saisissez une barre en hauteur et suspendez-vous en gardant les épaules actives. Respirez et redescendez avec contrôle.", "Agarra una barra alta y cuélgate con los hombros activos. Sigue respirando y baja con control.", "Greife eine hohe Stange und hänge mit aktiven Schultern. Atme weiter und steige kontrolliert ab.", "Afferra una sbarra in alto e resta appeso con spalle attive. Continua a respirare e scendi con controllo.", "Pak een hoge stang vast en hang met actieve schouders. Blijf ademen en stap gecontroleerd af.", "أمسك عقلة مرتفعة وتعلّق مع تنشيط الكتفين. استمر في التنفس وانزل بتحكم."],
  "nordic": ["Kneel with ankles anchored. Keep hips extended as you lower forward; catch yourself with your hands and return.", "À genoux, chevilles retenues, gardez les hanches tendues en descendant vers l’avant ; rattrapez-vous avec les mains et revenez.", "De rodillas con los tobillos sujetos, mantén las caderas extendidas al bajar hacia delante; apóyate con las manos y vuelve.", "Knie mit fixierten Knöcheln. Halte die Hüfte gestreckt beim Vorbeugen, fange dich mit den Händen ab und kehre zurück.", "In ginocchio con caviglie bloccate, mantieni le anche estese mentre scendi in avanti; fermati con le mani e torna.", "Kniel met je enkels vast. Houd je heupen gestrekt terwijl je voorover zakt, vang jezelf met je handen op en keer terug.", "اجثُ مع تثبيت الكاحلين. أبقِ الوركين ممدودين أثناء النزول للأمام؛ استند بيديك ثم عد."],
  "bridge": ["Lie on your back with knees bent and feet planted. Press through your feet to raise your hips, then lower slowly.", "Sur le dos, genoux fléchis et pieds au sol, poussez dans les pieds pour lever les hanches, puis redescendez lentement.", "Boca arriba, rodillas flexionadas y pies apoyados, empuja con los pies para elevar las caderas y baja lentamente.", "Lege dich auf den Rücken, Knie gebeugt und Füße aufgestellt. Drücke über die Füße die Hüfte hoch und senke sie langsam.", "Supino, ginocchia piegate e piedi a terra, spingi sui piedi per sollevare le anche, poi scendi lentamente.", "Lig op je rug met gebogen knieën en voeten op de vloer. Duw via je voeten je heupen omhoog en laat langzaam zakken.", "استلقِ على ظهرك والركبتان مثنيتان والقدمان ثابتتان. اضغط بالقدمين لرفع الوركين ثم انزل ببطء."],
  "plank": ["Support yourself on forearms and toes. Keep a straight line from head to heels without letting your hips sag.", "En appui sur les avant-bras et les orteils, gardez une ligne droite de la tête aux talons sans laisser les hanches s’affaisser.", "Apóyate en antebrazos y puntas de los pies. Mantén una línea recta de cabeza a talones sin dejar caer las caderas.", "Stütze dich auf Unterarme und Zehen. Halte eine gerade Linie von Kopf bis Fersen, ohne die Hüfte durchhängen zu lassen.", "In appoggio su avambracci e punte dei piedi, mantieni una linea retta dalla testa ai talloni senza far cedere le anche.", "Steun op je onderarmen en tenen. Houd een rechte lijn van hoofd tot hielen zonder je heupen te laten zakken.", "استند إلى الساعدين وأصابع القدمين. حافظ على خط مستقيم من الرأس للكعبين دون هبوط الوركين."],
  "sidePlank": ["Place your forearm under your shoulder, legs stacked. Lift your hips and hold, then lower; repeat on the other side.", "Placez l’avant-bras sous l’épaule, jambes superposées. Levez les hanches et tenez, puis redescendez ; changez de côté.", "Coloca el antebrazo bajo el hombro, piernas apiladas. Eleva las caderas y mantén, baja y repite al otro lado.", "Setze den Unterarm unter die Schulter, Beine übereinander. Hebe die Hüfte und halte, senke sie und wechsle die Seite.", "Metti l’avambraccio sotto la spalla, gambe sovrapposte. Solleva le anche e tieni, poi scendi e ripeti dall’altro lato.", "Plaats je onderarm onder je schouder, benen op elkaar. Hef je heupen en houd vast, zak en herhaal aan de andere kant.", "ضع الساعد تحت الكتف والساقين فوق بعضهما. ارفع الوركين واثبت ثم انزل وكرر على الجانب الآخر."],
  "hollow": ["Lie on your back, brace and lift shoulders and legs only as far as your lower back stays down.", "Sur le dos, gainez et levez épaules et jambes seulement tant que le bas du dos reste au sol.", "Boca arriba, activa el abdomen y eleva hombros y piernas solo hasta donde la zona lumbar permanezca en el suelo.", "Lege dich auf den Rücken, spanne den Rumpf an und hebe Schultern und Beine nur so weit, wie der untere Rücken am Boden bleibt.", "Supino, contrai il busto e solleva spalle e gambe solo finché la zona lombare resta a terra.", "Lig op je rug, span je romp aan en hef schouders en benen alleen zover als je onderrug op de grond blijft.", "استلقِ على ظهرك وشد الجذع وارفع الكتفين والساقين فقط بقدر بقاء أسفل الظهر على الأرض."],
  "wallSit": ["Lean your back against a wall and slide down to a comfortable knee bend. Keep feet planted and hold.", "Dos contre un mur, descendez jusqu’à une flexion confortable des genoux. Gardez les pieds au sol et tenez.", "Apoya la espalda en la pared y deslízate hasta una flexión cómoda de rodillas. Mantén los pies apoyados y aguanta.", "Lehne den Rücken an eine Wand und rutsche bis zu einer angenehmen Kniebeugung ab. Füße bleiben am Boden; halte die Position.", "Appoggia la schiena al muro e scendi fino a piegare le ginocchia comodamente. Piedi a terra, mantieni la posizione.", "Leun met je rug tegen een muur en zak tot een prettige kniebuiging. Houd je voeten op de grond en blijf zitten.", "اسند ظهرك للحائط وانزلق لثني مريح للركبتين. أبقِ القدمين ثابتتين واثبت."],
  "carry": ["Hold weights at your sides, stand tall and walk steadily. Put them down carefully before your grip or posture fails.", "Charges sur les côtés, tenez-vous droit et marchez régulièrement. Reposez-les prudemment avant de perdre la prise ou la posture.", "Sujeta las pesas a los lados, mantente erguido y camina con ritmo. Déjalas con cuidado antes de perder el agarre o la postura.", "Halte Gewichte seitlich, stehe aufrecht und gehe gleichmäßig. Stelle sie vorsichtig ab, bevor Griff oder Haltung nachlassen.", "Pesi ai fianchi, postura eretta, cammina con passo regolare. Appoggiali con cautela prima che presa o postura cedano.", "Houd gewichten naast je, sta rechtop en loop rustig. Zet ze voorzichtig neer voordat je grip of houding verslechtert.", "أمسك الأوزان بجانبيك وقف منتصباً وامشِ بثبات. ضعها بحذر قبل ضعف القبضة أو الوضعية."],
  "chairPress": ["Sit tall with a band anchored behind you. Press your hands forward at chest height, then return slowly.", "Assis droit, élastique fixé derrière vous, poussez les mains devant à hauteur de poitrine puis revenez lentement.", "Siéntate erguido con una banda anclada detrás. Empuja las manos hacia delante a la altura del pecho y vuelve despacio.", "Sitze aufrecht, Band hinter dir befestigt. Drücke die Hände auf Brusthöhe nach vorn und führe sie langsam zurück.", "Siediti eretto con elastico fissato dietro. Spingi le mani avanti all’altezza del petto, poi ritorna lentamente.", "Zit rechtop met een band achter je bevestigd. Duw je handen op borsthoogte naar voren en keer langzaam terug.", "اجلس منتصباً وشريط مثبت خلفك. ادفع يديك للأمام عند مستوى الصدر ثم عد ببطء."],
  "wallPush": ["Place hands on a wall at chest height, step back and keep your body straight. Bend elbows toward the wall, then press away.", "Mains au mur à hauteur de poitrine, reculez les pieds, corps aligné. Fléchissez les coudes vers le mur, puis repoussez.", "Apoya las manos en la pared a la altura del pecho, aleja los pies y mantén el cuerpo recto. Flexiona los codos hacia la pared y empuja.", "Setze die Hände auf Brusthöhe an die Wand, tritt zurück und halte den Körper gerade. Beuge die Ellenbogen zur Wand und drücke dich weg.", "Mani sul muro all’altezza del petto, piedi indietro e corpo allineato. Piega i gomiti verso il muro, poi spingi via.", "Zet je handen op borsthoogte tegen de muur, stap achteruit en houd je lichaam recht. Buig je ellebogen naar de muur en duw weg.", "ضع يديك على الحائط عند مستوى الصدر وابتعد بقدميك مع استقامة الجسم. اثنِ المرفقين نحو الحائط ثم ادفع بعيداً."],
  "chairStand": ["Sit on a stable chair with feet planted. Lean slightly forward, stand up, then sit back down slowly.", "Assis sur une chaise stable, pieds au sol, penchez-vous légèrement en avant, levez-vous puis rasseyez-vous lentement.", "Siéntate en una silla estable con los pies apoyados. Inclínate un poco hacia delante, levántate y vuelve a sentarte lentamente.", "Sitze auf einem stabilen Stuhl mit Füßen am Boden. Lehne dich leicht vor, stehe auf und setze dich langsam wieder.", "Siediti su una sedia stabile con piedi a terra. Inclinati leggermente avanti, alzati e siediti di nuovo lentamente.", "Zit op een stabiele stoel met voeten op de vloer. Leun iets naar voren, sta op en ga langzaam weer zitten.", "اجلس على كرسي ثابت وقدماك على الأرض. انحنِ قليلاً للأمام وقف ثم اجلس مجدداً ببطء."],
  "seatedMarch": ["Sit tall with feet on the floor. Lift one knee, lower it, then alternate sides at a steady pace.", "Assis droit, pieds au sol, levez un genou puis reposez-le et alternez les côtés à rythme régulier.", "Siéntate erguido con los pies en el suelo. Eleva una rodilla, bájala y alterna los lados a ritmo constante.", "Sitze aufrecht mit Füßen am Boden. Hebe ein Knie, senke es und wechsle im gleichmäßigen Tempo die Seite.", "Siediti eretto con piedi a terra. Solleva un ginocchio, abbassalo e alterna i lati a ritmo regolare.", "Zit rechtop met voeten op de grond. Hef één knie, laat zakken en wissel in een gelijkmatig tempo af.", "اجلس منتصباً وقدماك على الأرض. ارفع ركبة وأنزلها ثم بدّل الجانبين بإيقاع ثابت."],
  "pullApart": ["Hold a band in front at shoulder height. Pull hands apart without shrugging, then bring them together slowly.", "Tenez un élastique devant vous à hauteur d’épaules. Écartez les mains sans hausser les épaules, puis rapprochez-les lentement.", "Sujeta una banda delante a la altura de los hombros. Separa las manos sin encoger los hombros y júntalas despacio.", "Halte ein Band auf Schulterhöhe vor dir. Ziehe die Hände auseinander ohne die Schultern zu heben und führe sie langsam zusammen.", "Tieni un elastico davanti all’altezza delle spalle. Separa le mani senza sollevare le spalle, poi riavvicinale lentamente.", "Houd een band voor je op schouderhoogte. Trek je handen uit elkaar zonder je schouders op te halen en breng ze langzaam samen.", "أمسك شريطاً أمامك عند مستوى الكتفين. باعد بين اليدين دون رفع الكتفين ثم قرّبهما ببطء."],
  "deadBug": ["Lie on your back with knees over hips and arms up. Slowly extend the opposite arm and leg, return, then switch sides.", "Sur le dos, genoux au-dessus des hanches et bras levés, tendez lentement le bras et la jambe opposés, revenez puis changez de côté.", "Boca arriba, rodillas sobre las caderas y brazos arriba, estira lentamente el brazo y la pierna opuestos, vuelve y cambia de lado.", "Lege dich auf den Rücken, Knie über der Hüfte und Arme oben. Strecke langsam gegenüberliegenden Arm und Bein, kehre zurück und wechsle.", "Supino, ginocchia sopra le anche e braccia in alto, distendi lentamente braccio e gamba opposti, torna e cambia lato.", "Lig op je rug, knieën boven je heupen en armen omhoog. Strek langzaam tegenovergestelde arm en been, keer terug en wissel.", "استلقِ على ظهرك والركبتان فوق الوركين والذراعان للأعلى. مدّ الذراع والساق المتقابلتين ببطء ثم عد وبدّل."],
  "birdDog": ["Start on hands and knees. Reach one arm forward and the opposite leg back without twisting your hips, then return and switch.", "À quatre pattes, tendez un bras devant et la jambe opposée derrière sans tourner le bassin, revenez puis changez de côté.", "A cuatro apoyos, extiende un brazo delante y la pierna opuesta atrás sin girar las caderas; vuelve y cambia.", "Im Vierfüßlerstand strecke einen Arm vor und das gegenüberliegende Bein zurück, ohne die Hüfte zu drehen; kehre zurück und wechsle.", "A quattro zampe, allunga un braccio avanti e la gamba opposta indietro senza ruotare le anche; torna e cambia.", "Begin op handen en knieën. Strek één arm naar voren en het tegenovergestelde been naar achter zonder je heupen te draaien; keer terug en wissel.", "ابدأ على اليدين والركبتين. مدّ ذراعاً للأمام والساق المقابلة للخلف دون تدوير الوركين، ثم عد وبدّل."],
  "catCow": ["On hands and knees, gently round your back, then slowly arch to a comfortable range while breathing.", "À quatre pattes, arrondissez doucement le dos puis creusez-le lentement dans une amplitude confortable en respirant.", "A cuatro apoyos, redondea suavemente la espalda y después arquéala lentamente dentro de un rango cómodo mientras respiras.", "Im Vierfüßlerstand runde den Rücken sanft und wölbe ihn dann langsam in angenehmem Maß, während du atmest.", "A quattro zampe, arrotonda dolcemente la schiena, poi inarcala lentamente entro un’ampiezza confortevole respirando.", "Maak op handen en knieën je rug rustig bol en hol hem daarna langzaam binnen een prettige beweging, terwijl je ademt.", "على اليدين والركبتين، دوّر ظهرك برفق ثم قوّسه ببطء ضمن مدى مريح مع التنفس."],
  "heelSlide": ["Lie on your back with one knee bent. Slide that heel along the floor to straighten the leg, then slide it back.", "Sur le dos, un genou fléchi, faites glisser ce talon au sol pour tendre la jambe, puis ramenez-le.", "Boca arriba con una rodilla flexionada, desliza ese talón por el suelo para estirar la pierna y vuelve a deslizarlo.", "Lege dich mit einem gebeugten Knie auf den Rücken. Schiebe diese Ferse am Boden entlang, bis das Bein gestreckt ist, und ziehe sie zurück.", "Supino con un ginocchio piegato, fai scorrere quel tallone sul pavimento per distendere la gamba, poi riportalo indietro.", "Lig op je rug met één knie gebogen. Schuif die hiel over de vloer om het been te strekken en schuif terug.", "استلقِ على ظهرك مع ثني ركبة. أزلق كعبها على الأرض لمدّ الساق ثم أعده."],
  "reach": ["Stand or sit tall with ribs relaxed. Reach both arms overhead as comfortable, then lower slowly.", "Debout ou assis droit, côtes détendues, levez les deux bras au-dessus de la tête sans gêne puis redescendez lentement.", "De pie o sentado erguido, costillas relajadas, eleva ambos brazos por encima de la cabeza sin molestias y baja despacio.", "Stehe oder sitze aufrecht, Rippen entspannt. Hebe beide Arme angenehm weit über den Kopf und senke sie langsam.", "In piedi o seduto eretto, costole rilassate, porta entrambe le braccia sopra la testa senza fastidio, poi abbassa lentamente.", "Sta of zit rechtop met ontspannen ribben. Reik beide armen comfortabel boven je hoofd en laat ze langzaam zakken.", "قف أو اجلس منتصباً مع إرخاء الأضلاع. ارفع الذراعين فوق الرأس بمدى مريح ثم أنزلهما ببطء."],
  "balance": ["Stand near stable support and lift one foot slightly. Hold while breathing, then switch sides.", "Debout près d’un appui stable, décollez légèrement un pied. Tenez en respirant, puis changez de côté.", "De pie cerca de un apoyo estable, eleva ligeramente un pie. Mantén respirando y cambia de lado.", "Stehe neben einer stabilen Stütze und hebe einen Fuß leicht. Halte die Position beim Atmen, dann wechsle die Seite.", "In piedi vicino a un sostegno stabile, solleva leggermente un piede. Mantieni respirando, poi cambia lato.", "Sta bij een stabiele steun en til één voet iets op. Houd vast terwijl je ademt en wissel van kant.", "قف قرب مسند ثابت وارفع قدماً قليلاً. اثبت مع التنفس ثم بدّل الجانب."],
  "twist": ["Sit tall with feet planted. Gently rotate your upper body to one side, return to center, then switch sides.", "Assis droit, pieds au sol, tournez doucement le buste d’un côté, revenez au centre puis changez de côté.", "Siéntate erguido con los pies apoyados. Gira suavemente el tronco a un lado, vuelve al centro y cambia.", "Sitze aufrecht mit Füßen am Boden. Drehe den Oberkörper sanft zu einer Seite, kehre zur Mitte zurück und wechsle.", "Siediti eretto con piedi a terra. Ruota dolcemente il busto da un lato, torna al centro e cambia lato.", "Zit rechtop met voeten op de grond. Draai je bovenlichaam rustig naar één kant, terug naar het midden en wissel.", "اجلس منتصباً وقدماك ثابتتان. أدر جذعك برفق إلى جانب ثم عد للوسط وبدّل الجانب."],
  "sled": ["Lean into the handles with straight arms and a braced trunk. Push the sled forward using short, steady steps.", "Penchez-vous contre les poignées, bras tendus et buste gainé. Poussez le traîneau avec de petits pas réguliers.", "Inclínate sobre las asas con brazos extendidos y tronco firme. Empuja el trineo hacia delante con pasos cortos y constantes.", "Lehne dich mit gestreckten Armen und stabilem Rumpf in die Griffe. Schiebe den Schlitten mit kurzen, gleichmäßigen Schritten vor.", "Inclinati sulle maniglie con braccia distese e busto stabile. Spingi la slitta avanti con passi brevi e regolari.", "Leun tegen de grepen met gestrekte armen en een stevige romp. Duw de slee vooruit met korte, gelijkmatige stappen.", "انحنِ على المقبضين بذراعين ممدودتين وجذع ثابت. ادفع الزلاجة للأمام بخطوات قصيرة منتظمة."],
  "rower": ["At the catch, bend knees and straighten arms. Push with legs, lean back slightly, then pull the handle; reverse the sequence to return.", "Au départ, genoux fléchis et bras tendus, poussez avec les jambes, penchez légèrement le buste en arrière puis tirez la poignée ; inversez pour revenir.", "Al inicio, rodillas flexionadas y brazos rectos; empuja con las piernas, inclínate un poco atrás y tira del asa. Invierte el orden para volver.", "Am Anfang Knie gebeugt und Arme gestreckt: Drücke mit den Beinen, lehne dich leicht zurück und ziehe den Griff; kehre in umgekehrter Reihenfolge zurück.", "Alla partenza, ginocchia piegate e braccia distese: spingi con le gambe, inclinati leggermente indietro e tira la maniglia; inverti la sequenza per tornare.", "Bij de start zijn knieën gebogen en armen gestrekt. Duw met je benen, leun iets achterover en trek de greep; keer in omgekeerde volgorde terug.", "في البداية الركبتان مثنيتان والذراعان ممدودتان. ادفع بالساقين ومل قليلاً للخلف ثم اسحب المقبض؛ اعكس الترتيب للعودة."],
  "bike": ["Adjust the seat so your knee is slightly bent at the bottom of the pedal stroke. Pedal smoothly with relaxed shoulders.", "Réglez la selle pour garder le genou légèrement fléchi en bas du pédalage. Pédalez souplement, épaules détendues.", "Ajusta el sillín para que la rodilla quede algo flexionada al final de la pedalada. Pedalea suavemente con hombros relajados.", "Stelle den Sattel so ein, dass das Knie unten leicht gebeugt bleibt. Tritt gleichmäßig und entspanne die Schultern.", "Regola la sella in modo che il ginocchio resti leggermente piegato in fondo alla pedalata. Pedala fluidamente con spalle rilassate.", "Stel het zadel zo af dat je knie onderaan de trapbeweging licht gebogen blijft. Trap soepel met ontspannen schouders.", "اضبط المقعد بحيث تبقى الركبة مثنية قليلاً أسفل دورة الدواسة. بدّل بسلاسة مع إرخاء الكتفين."],
  "run": ["Run with relaxed shoulders and short, comfortable strides. Alternate faster running with easy walking or jogging for recovery.", "Courez épaules détendues, avec des foulées courtes et confortables. Alternez course plus rapide et marche ou jogging facile pour récupérer.", "Corre con hombros relajados y zancadas cortas y cómodas. Alterna carrera rápida con caminar o trotar suave para recuperar.", "Laufe mit entspannten Schultern und kurzen, angenehmen Schritten. Wechsle schnelleres Laufen mit lockerem Gehen oder Joggen zur Erholung ab.", "Corri con spalle rilassate e passi brevi e confortevoli. Alterna corsa più veloce a camminata o corsa leggera per recuperare.", "Ren met ontspannen schouders en korte, comfortabele passen. Wissel sneller rennen af met rustig wandelen of joggen om te herstellen.", "اركض بكتفين مرتخيين وخطوات قصيرة مريحة. بدّل بين الجري الأسرع والمشي أو الهرولة الخفيفة للتعافي."]
};
Object.keys(MOVEMENT_COPY).forEach(k => MOVEMENT_LANGS.forEach((l,i) => { T[l]['movement.guide.'+k] = MOVEMENT_COPY[k][i]; }));
